import express from "express";
import cors from "cors";
import dotenv from "dotenv";

dotenv.config();

const app = express();
const port = Number(process.env.PORT ?? 4000);

app.use(cors());
app.use(express.json({ limit: "10mb" }));

function buildOptimizedPrompt(userPrompt: string, style: string) {
  const normalizedPrompt = userPrompt.replace(/\s+/g, " ").trim();

  return [
    "Diseño para grabado láser sobre un vaso personalizado.",
    `Tema: ${normalizedPrompt}.`,
    `Estilo: ${style}.`,
    "Solo mostrar el diseño.",
    "Sin fondo.",
    "Fondo blanco.",
    "Líneas limpias.",
    "Alta resolución.",
    "Vector.",
    "Apto para grabado láser.",
  ].join("\n");
}

function buildPollinationsUrl(prompt: string) {
  return `https://image.pollinations.ai/prompt/${encodeURIComponent(prompt)}`;
}

app.get("/health", (_req, res) => {
  res.json({ ok: true });
});

app.post("/api/generar-diseno", (req, res) => {
  try {
    const { prompt } = req.body as { prompt?: string };

    if (!prompt || typeof prompt !== "string" || prompt.trim().length < 3) {
      return res.status(400).json({ error: "Proporciona un prompt válido." });
    }

    const styles = ["Minimalista", "Alto contraste", "Elegante", "Premium"];
    const images = styles.map((style, index) => {
      const optimizedPrompt = buildOptimizedPrompt(prompt.trim(), style);
      return {
        id: index + 1,
        title: style,
        prompt: optimizedPrompt,
        imageUrl: `${buildPollinationsUrl(optimizedPrompt)}?seed=${index + 1}`,
      };
    });

    res.json({ prompt: prompt.trim(), images });
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : "Error desconocido";
    console.error("Error en /api/generar-diseno:", error);
    res.status(500).json({ error: message });
  }
});

app.listen(port, () => {
  console.log(`Backend escuchando en http://localhost:${port}`);
});

