/*
 * D&C Innovación design system.
 * Neutral premium palette (white / near-black / greys) with a single wine accent
 * taken from the brand logo. All colors in oklch.
 */

@theme inline {
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --radius-2xl: calc(var(--radius) + 8px);
  --radius-3xl: calc(var(--radius) + 12px);
  --radius-4xl: calc(var(--radius) + 16px);
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-wine: var(--wine);
  --color-wine-soft: var(--wine-soft);
  --color-wine-foreground: var(--wine-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-ring-offset-background: var(--background);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
  --font-sans: "Plus Jakarta Sans", ui-sans-serif, system-ui, sans-serif;
  --font-display: "Playfair Display", ui-serif, Georgia, serif;
}

:root {
  --radius: 0.875rem;
  --background: oklch(1 0 0);
  --foreground: oklch(0.18 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.18 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.18 0 0);
  --primary: oklch(0.18 0 0);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.968 0 0);
  --secondary-foreground: oklch(0.25 0 0);
  --muted: oklch(0.968 0 0);
  --muted-foreground: oklch(0.53 0 0);
  --accent: oklch(0.968 0 0);
  --accent-foreground: oklch(0.25 0 0);

  /* Brand accent: wine from the logo */
  --wine: oklch(0.38 0.13 15);
  --wine-soft: oklch(0.96 0.02 15);
  --wine-foreground: oklch(0.99 0 0);

  --destructive: oklch(0.577 0.245 27.325);
  --destructive-foreground: oklch(0.99 0 0);
  --border: oklch(0.922 0 0);
  --input: oklch(0.922 0 0);
  --ring: oklch(0.38 0.13 15);
  --chart-1: oklch(0.38 0.13 15);
  --chart-2: oklch(0.55 0.08 15);
  --chart-3: oklch(0.7 0.04 15);
  --chart-4: oklch(0.45 0 0);
  --chart-5: oklch(0.75 0 0);
  --sidebar: oklch(0.984 0 0);
  --sidebar-foreground: oklch(0.18 0 0);
  --sidebar-primary: oklch(0.18 0 0);
  --sidebar-primary-foreground: oklch(0.99 0 0);
  --sidebar-accent: oklch(0.968 0 0);
  --sidebar-accent-foreground: oklch(0.25 0 0);
  --sidebar-border: oklch(0.922 0 0);
  --sidebar-ring: oklch(0.38 0.13 15);

  --shadow-soft: 0 1px 2px oklch(0 0 0 / 0.04), 0 8px 24px -12px oklch(0 0 0 / 0.12);
  --shadow-float: 0 24px 60px -28px oklch(0 0 0 / 0.28);
  --gradient-fade: linear-gradient(180deg, oklch(1 0 0), oklch(0.975 0 0));
}

.dark {
  --background: oklch(0.16 0 0);
  --foreground: oklch(0.98 0 0);
  --card: oklch(0.21 0 0);
  --card-foreground: oklch(0.98 0 0);
  --popover: oklch(0.21 0 0);
  --popover-foreground: oklch(0.98 0 0);
  --primary: oklch(0.98 0 0);
  --primary-foreground: oklch(0.18 0 0);
  --secondary: oklch(0.26 0 0);
  --secondary-foreground: oklch(0.98 0 0);
  --muted: oklch(0.26 0 0);
  --muted-foreground: oklch(0.72 0 0);
  --accent: oklch(0.26 0 0);
  --accent-foreground: oklch(0.98 0 0);
  --wine: oklch(0.52 0.14 15);
  --wine-soft: oklch(0.26 0.04 15);
  --wine-foreground: oklch(0.99 0 0);
  --border: oklch(1 0 0 / 10%);
  --input: oklch(1 0 0 / 15%);
  --ring: oklch(0.52 0.14 15);
  --sidebar: oklch(0.21 0 0);
  --sidebar-foreground: oklch(0.98 0 0);
  --sidebar-primary: oklch(0.52 0.14 15);
  --sidebar-primary-foreground: oklch(0.99 0 0);
  --sidebar-accent: oklch(0.26 0 0);
  --sidebar-accent-foreground: oklch(0.98 0 0);
  --sidebar-border: oklch(1 0 0 / 10%);
  --sidebar-ring: oklch(0.52 0.14 15);
}

@layer base {
  * {
    border-color: var(--color-border);
  }

  html {
    scroll-behavior: smooth;
    scroll-padding-top: 6rem;
  }

  html {
    font-size: 17px;
  }

  body {
    background-color: var(--color-background);
    color: var(--color-foreground);
    font-family: var(--font-sans);
    font-size: 1rem;
    line-height: 1.7;
    -webkit-font-smoothing: antialiased;
  }

  h1,
  h2,
  h3 {
    letter-spacing: -0.025em;
  }

  p,
  li,
  span,
  label,
  button,
  input,
  textarea {
    font-size: inherit;
  }
}

@utility glass {
  background-color: color-mix(in oklab, var(--color-background) 72%, transparent);
  backdrop-filter: blur(18px) saturate(140%);
  -webkit-backdrop-filter: blur(18px) saturate(140%);
}

@utility shadow-soft {
  box-shadow: var(--shadow-soft);
}

@utility shadow-float {
  box-shadow: var(--shadow-float);
}

@utility text-balance-tight {
  text-wrap: balance;
}

